import{_ as e,c as r,o as h,ah as i}from"./chunks/framework.Dnh4IO1K.js";const b=JSON.parse('{"title":"比吉。原筮元永貞","description":"周易集解 - 比吉。原筮元永貞","frontmatter":{"title":"比吉。原筮元永貞","description":"周易集解 - 比吉。原筮元永貞"},"headers":[],"relativePath":"classics/jijie/008.md","filePath":"classics/jijie/008.md"}'),l={name:"classics/jijie/008.md"};function n(d,a,p,t,s,c){return h(),r("div",null,[...a[0]||(a[0]=[i('<h1 id="比吉。原筮元永貞" tabindex="-1">比吉。原筮元永貞 <a class="header-anchor" href="#比吉。原筮元永貞" aria-label="Permalink to “比吉。原筮元永貞”">​</a></h1><h2 id="比吉。原筮元永貞-1" tabindex="-1">比吉。原筮元永貞 <a class="header-anchor" href="#比吉。原筮元永貞-1" aria-label="Permalink to “比吉。原筮元永貞”">​</a></h2><h2 id="卦辭" tabindex="-1">卦辭 <a class="header-anchor" href="#卦辭" aria-label="Permalink to “卦辭”">​</a></h2><p>比吉。原筮元永貞，無咎。不寧方來，後夫兇。</p><h2 id="卦辭注" tabindex="-1">卦辭注 <a class="header-anchor" href="#卦辭注" aria-label="Permalink to “卦辭注”">​</a></h2><p>《序卦》曰：眾必有所比，故受之以比。</p><p>崔憬曰：方以類聚，物以群分，人眾則群類必有所比矣。上比相阿黨，下比相和親也。相黨則相親，故言比者比也。</p><p>虞翻曰：師二上之五得位，眾陰順從，比而輔之，故吉。與大有旁通。</p><p>《子夏傳》曰：地得水而柔，水得土而流，比之象也。夫兇者，生乎乖爭，今既親比，故雲比吉也。</p><h2 id="彖" tabindex="-1">彖 <a class="header-anchor" href="#彖" aria-label="Permalink to “彖”">​</a></h2><p>《彖》曰：比，吉也。比，輔也，下順從也。原筮元永貞，無咎，以剛中也。不寧方來，上下應也。後夫兇，其道窮也。</p><h2 id="彖傳注" tabindex="-1">彖傳注 <a class="header-anchor" href="#彖傳注" aria-label="Permalink to “彖傳注”">​</a></h2><p>崔憬曰：下比於上，是下順也。</p><p>蜀才曰：此本師卦。</p><p>案：六五降二，九二升五，剛往得中，為比之主。故能原究筮道，以求長正而無咎矣。</p><p>虞翻曰：水性流動，故不寧。坤陰為方，上下應之，故方來也。</p><p>虞翻曰：後謂上，夫謂五也。坎為後，艮為背。上位在背後，無應乘陽，故後夫兇也。</p><p>荀爽曰：後夫謂上六。逆禮乘陽，不比聖王，其義當誅，故其道窮兇也。</p><h2 id="象" tabindex="-1">象 <a class="header-anchor" href="#象" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：地上有水，比。先王以建萬國，親諸侯。</p><h2 id="象傳注" tabindex="-1">象傳注 <a class="header-anchor" href="#象傳注" aria-label="Permalink to “象傳注”">​</a></h2><p>何晏曰：水性潤下，今在地上，更相浸潤，比之義也。</p><p>虞翻曰：先王謂五。初陽已復。震為建，為諸侯。坤為萬國，為腹，坎為心，腹心親比，故「以建萬國，親諸侯」。《詩》曰「公侯腹心」，是其義也。</p><h2 id="初六" tabindex="-1">初六 <a class="header-anchor" href="#初六" aria-label="Permalink to “初六”">​</a></h2><p>初六，有孚比之，無咎。有孚盈缶，終來有它吉。</p><h2 id="初六注" tabindex="-1">初六注 <a class="header-anchor" href="#初六注" aria-label="Permalink to “初六注”">​</a></h2><p>虞翻曰：孚謂五。初失位，變來得正，故無咎也。</p><p>荀爽曰：初在應外，以喻殊俗，聖王之信，光被四表。絕域殊俗，皆來親比，故無咎也。</p><p>虞翻曰：坤器為缶。坎水流坤。初動成屯。屯者，盈也，故盈缶。終變得正，故「終來有它吉」。在內稱來也。</p><h2 id="象-1" tabindex="-1">象 <a class="header-anchor" href="#象-1" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：比之初六，有它吉也。</p><h2 id="象傳注-1" tabindex="-1">象傳注 <a class="header-anchor" href="#象傳注-1" aria-label="Permalink to “象傳注”">​</a></h2><p>荀爽曰：缶者應內，以喻中國。孚既盈滿中國，終來及初，非應，故曰它也。《象》雲有它吉者，謂信及非應，然後吉也。</p><h2 id="六二" tabindex="-1">六二 <a class="header-anchor" href="#六二" aria-label="Permalink to “六二”">​</a></h2><p>六二，比之自內，貞吉。</p><h2 id="六二注" tabindex="-1">六二注 <a class="header-anchor" href="#六二注" aria-label="Permalink to “六二注”">​</a></h2><p>乾寶曰：二在坤中。坤，國之象也。得位應五，而體寬大，君樂民人自得之象也，故曰「比之自內，貞吉」矣。</p><h2 id="象-2" tabindex="-1">象 <a class="header-anchor" href="#象-2" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：比之自內，不自失也。</p><h2 id="象傳注-2" tabindex="-1">象傳注 <a class="header-anchor" href="#象傳注-2" aria-label="Permalink to “象傳注”">​</a></h2><p>崔憬曰：自內而比，不失已親也。</p><h2 id="六三" tabindex="-1">六三 <a class="header-anchor" href="#六三" aria-label="Permalink to “六三”">​</a></h2><p>六三，比之匪人。</p><h2 id="六三注" tabindex="-1">六三注 <a class="header-anchor" href="#六三注" aria-label="Permalink to “六三注”">​</a></h2><p>虞翻曰：匪，非也，失位無應，三又多兇，體剝傷象，弒父弒君，故曰匪人。</p><h2 id="象-3" tabindex="-1">象 <a class="header-anchor" href="#象-3" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：比之匪人，不亦傷乎。</p><h2 id="象傳注-3" tabindex="-1">象傳注 <a class="header-anchor" href="#象傳注-3" aria-label="Permalink to “象傳注”">​</a></h2><p>乾寶曰：六三乙卯，坤之鬼吏。要比之家，有土之君也。周為木德，卯為木辰，同姓之國也。爻失其位，辰體陰賊，管蔡之象也。比建萬國，唯去此人，故曰比之匪人，不亦傷王政也。</p><h2 id="六四" tabindex="-1">六四 <a class="header-anchor" href="#六四" aria-label="Permalink to “六四”">​</a></h2><p>六四，外比之，貞吉。</p><h2 id="六四注" tabindex="-1">六四注 <a class="header-anchor" href="#六四注" aria-label="Permalink to “六四注”">​</a></h2><p>虞翻曰：在外體，故稱外。得位比賢，故貞吉也。</p><h2 id="象-4" tabindex="-1">象 <a class="header-anchor" href="#象-4" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：外比於賢，以從上也。</p><h2 id="象傳注-4" tabindex="-1">象傳注 <a class="header-anchor" href="#象傳注-4" aria-label="Permalink to “象傳注”">​</a></h2><p>乾寶曰：四為三公，在比之家，而得其位。上比聖主，下御列國，方伯之象也。能外親九服，賢德之君，務宣上志，綏萬邦也。故曰「外比於賢，以從上也」。</p><h2 id="九五" tabindex="-1">九五 <a class="header-anchor" href="#九五" aria-label="Permalink to “九五”">​</a></h2><p>九五，顯比。王用三驅，失前禽，邑人不誡，吉。</p><h2 id="九五注" tabindex="-1">九五注 <a class="header-anchor" href="#九五注" aria-label="Permalink to “九五注”">​</a></h2><p>虞翻曰：五貴多功，得位正中，初三以變體重明，故顯比。謂顯諸仁也。</p><p>虞翻曰：坎五稱王。三驅，謂驅下三陰，不及於初，故失前禽。謂初已變成震，震為鹿，為驚走，鹿之斯奔，則失前禽也。</p><p>虞翻曰：坤為邑師，震為人師。時坤虛無君，使師二上居五中，故不誡吉也。</p><h2 id="象-5" tabindex="-1">象 <a class="header-anchor" href="#象-5" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：顯比之吉，位正中也。舍逆取順，失前禽也。邑人不誡，上使中也。</p><h2 id="象傳注-5" tabindex="-1">象傳注 <a class="header-anchor" href="#象傳注-5" aria-label="Permalink to “象傳注”">​</a></h2><p>虞翻曰：謂離象明。正上中也。</p><p>虞翻曰：背上六，故舍逆。據三陰，故取順。不及初，故失前禽。</p><p>虞翻曰：謂二，使師二上居五中。</p><h2 id="上六" tabindex="-1">上六 <a class="header-anchor" href="#上六" aria-label="Permalink to “上六”">​</a></h2><p>上六，比之無首，兇。</p><h2 id="上六注" tabindex="-1">上六注 <a class="header-anchor" href="#上六注" aria-label="Permalink to “上六注”">​</a></h2><p>荀爽曰：陽欲無首，陰以大終。陰而無首，不以大終。故兇也。</p><p>虞翻曰：首，始也。陰道無成，而代有終，無首，兇。</p><h2 id="象-6" tabindex="-1">象 <a class="header-anchor" href="#象-6" aria-label="Permalink to “象”">​</a></h2><p>《象》曰：比之無首，無所終也。</p><h2 id="象傳注-6" tabindex="-1">象傳注 <a class="header-anchor" href="#象傳注-6" aria-label="Permalink to “象傳注”">​</a></h2><p>虞翻曰：迷失道，故無所終也。</p>',78)])])}const m=e(l,[["render",n]]);export{b as __pageData,m as default};
